// Page 1, or its retry page. Every field is checked here on the server; whitespace-only counts as empty.
const page = $('Fix Your Details').isExecuted ? $('Fix Your Details').last().json : $('Service Request Form').first().json;
const prefill = Object.fromEntries(["Your Name","Your Email","What do you need?"].map((k) => [k, String(page[k] ?? '')]));
const s = $('Service Request Settings').first().json;
const max = Number(s.max_attempts) || 3;
const attempt = $runIndex + 1;
const text = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const errors = [];
const result = (extra) => {
  const ok = errors.length === 0;
  return [{ json: { ok, retry: !ok && attempt < max, give_up: !ok && attempt >= max, error: errors.join(' '), attempt, max_attempts: max, prefill, ...extra } }];
};
// Page 1 choices and the branch each one opens. Keep in sync with the form's options and Route by Service.
const SERVICES = {"Repair something that stopped working":"repair","Install something new":"installation","Get a price quote":"quote"};
const name = text(page['Your Name']);
const email = text(page['Your Email']).toLowerCase();
const choice = text(page['What do you need?']);
if (!name) errors.push('Please enter your name.');
else if (name.length > 100) errors.push('Please keep your name under 100 characters.');
if (email.length > 254 || !/^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(email)) errors.push('Please enter a valid email address.');
if (!Object.hasOwn(SERVICES, choice)) errors.push('Please choose what you need from the list.');
return result({ name, email, service: SERVICES[choice] || '', service_choice: choice });

// Repair page: only shown when page 1 said "Repair".
const page = $input.first().json;
const prefill = Object.fromEntries(["What needs repair?","Describe the problem","How urgent is it?","Phone number","Preferred visit date"].map((k) => [k, String(page[k] ?? '')]));
const s = $('Service Request Settings').first().json;
const max = Number(s.max_attempts) || 3;
const attempt = $runIndex + 1;
const text = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const errors = [];
const result = (extra) => {
  const ok = errors.length === 0;
  return [{ json: { ok, retry: !ok && attempt < max, give_up: !ok && attempt >= max, error: errors.join(' '), attempt, max_attempts: max, prefill, ...extra } }];
};
// Dates are read in the workflow timezone, not the server's.
const checkDate = (v, what) => {
  const raw = text(v);
  const d = DateTime.fromISO(raw, { zone: $now.zoneName });
  const today = $now.startOf('day');
  const maxDays = Number(s.max_days_ahead) || 60;
  if (!raw || !/^\d{4}-\d{2}-\d{2}$/.test(raw) || !d.isValid) { errors.push('Please choose ' + what + '.'); return ''; }
  if (d < today) { errors.push('The ' + what.replace(/^an? /, '') + ' cannot be in the past.'); return ''; }
  if (d > today.plus({ days: maxDays })) { errors.push('Please choose ' + what + ' within the next ' + maxDays + ' days.'); return ''; }
  return d.toISODate();
};
const ITEMS = ["Heating or boiler","Air conditioning","Plumbing","Electrical","Appliance","Something else"];
const URGENCY = ["Emergency: no heat, a water leak or no power","Soon: within a few days","Flexible"];
const topic = text(page['What needs repair?']);
const description = String(page['Describe the problem'] ?? '').trim();
const urgency = text(page['How urgent is it?']);
const phone = text(page['Phone number']);
if (!ITEMS.includes(topic)) errors.push('Please choose what needs repair from the list.');
if (description.length < 10) errors.push('Please describe the problem in a few words (at least 10 characters).');
else if (description.length > 2000) errors.push('Please keep the description under 2000 characters.');
if (!URGENCY.includes(urgency)) errors.push('Please choose how urgent it is.');
const emergency = urgency === URGENCY[0];
if (phone && (!/^\+?[0-9 ().-]{7,20}$/.test(phone) || phone.replace(/\D/g, '').length < 7)) errors.push('Please enter a phone number with at least 7 digits.');
else if (emergency && !phone) errors.push('For an emergency we need a phone number so a technician can call you.');
const preferred_date = checkDate(page['Preferred visit date'], 'a visit date');
return result({ answers: { topic, description, urgency, phone, preferred_date }, priority: emergency ? 'urgent' : 'normal' });

// Installation page: only shown when page 1 said "Install".
const page = $input.first().json;
const prefill = Object.fromEntries(["What should we install?","How many units?","Property type","Preferred installation date","Access notes"].map((k) => [k, String(page[k] ?? '')]));
const s = $('Service Request Settings').first().json;
const max = Number(s.max_attempts) || 3;
const attempt = $runIndex + 1;
const text = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const errors = [];
const result = (extra) => {
  const ok = errors.length === 0;
  return [{ json: { ok, retry: !ok && attempt < max, give_up: !ok && attempt >= max, error: errors.join(' '), attempt, max_attempts: max, prefill, ...extra } }];
};
// Dates are read in the workflow timezone, not the server's.
const checkDate = (v, what) => {
  const raw = text(v);
  const d = DateTime.fromISO(raw, { zone: $now.zoneName });
  const today = $now.startOf('day');
  const maxDays = Number(s.max_days_ahead) || 60;
  if (!raw || !/^\d{4}-\d{2}-\d{2}$/.test(raw) || !d.isValid) { errors.push('Please choose ' + what + '.'); return ''; }
  if (d < today) { errors.push('The ' + what.replace(/^an? /, '') + ' cannot be in the past.'); return ''; }
  if (d > today.plus({ days: maxDays })) { errors.push('Please choose ' + what + ' within the next ' + maxDays + ' days.'); return ''; }
  return d.toISODate();
};
const ITEMS = ["Heat pump","Air conditioner","Water heater","EV charger","Something else"];
const PROPERTY = ["House","Apartment","Business premises"];
const maxUnits = Number(s.max_units) || 20;
const topic = text(page['What should we install?']);
const rawUnits = page['How many units?'];
const units = typeof rawUnits === 'number' ? rawUnits : (text(rawUnits) === '' ? NaN : Number(text(rawUnits)));
const property_type = text(page['Property type']);
const description = String(page['Access notes'] ?? '').trim();
if (!ITEMS.includes(topic)) errors.push('Please choose what we should install from the list.');
if (!Number.isInteger(units) || units < 1) errors.push('Please enter a whole number of units, at least 1.');
else if (units > maxUnits) errors.push('For more than ' + maxUnits + ' units please ask for a quote instead.');
if (!PROPERTY.includes(property_type)) errors.push('Please choose the property type.');
if (description.length > 1000) errors.push('Please keep the access notes under 1000 characters.');
const preferred_date = checkDate(page['Preferred installation date'], 'an installation date');
return result({ answers: { topic, units, property_type, description, preferred_date }, priority: 'normal' });

// Quote page: only shown when page 1 said "Quote".
const page = $input.first().json;
const prefill = Object.fromEntries(["What is the quote for?","Budget","When will you decide?","Company name"].map((k) => [k, String(page[k] ?? '')]));
const s = $('Service Request Settings').first().json;
const max = Number(s.max_attempts) || 3;
const attempt = $runIndex + 1;
const text = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const errors = [];
const result = (extra) => {
  const ok = errors.length === 0;
  return [{ json: { ok, retry: !ok && attempt < max, give_up: !ok && attempt >= max, error: errors.join(' '), attempt, max_attempts: max, prefill, ...extra } }];
};
const BUDGET = ["Under $1,000","$1,000 to $5,000","Over $5,000","Not sure yet"];
const TIMEFRAME = ["Within 2 weeks","Within 3 months","Just comparing prices"];
const description = String(page['What is the quote for?'] ?? '').trim();
const budget = text(page['Budget']);
const decision_timeframe = text(page['When will you decide?']);
const company = text(page['Company name']);
if (description.length < 10) errors.push('Please tell us what the quote is for (at least 10 characters).');
else if (description.length > 2000) errors.push('Please keep the description under 2000 characters.');
if (!BUDGET.includes(budget)) errors.push('Please choose a budget range.');
if (!TIMEFRAME.includes(decision_timeframe)) errors.push('Please choose when you will decide.');
if (company.length > 100) errors.push('Please keep the company name under 100 characters.');
return result({ answers: { topic: 'Price quote', description, budget, decision_timeframe, company }, priority: decision_timeframe === TIMEFRAME[0] ? 'hot lead' : 'normal' });

// The three branches meet here. Only the branch that ran has data, so read the one that matches the service.
const s = $('Service Request Settings').first().json;
const c = $('Check Contact Details').last().json;
const check = { repair: 'Check Repair Answers', installation: 'Check Installation Answers', quote: 'Check Quote Answers' }[c.service];
const b = $(check).last().json;
const a = b.answers;
const label = { repair: 'Repair', installation: 'Installation', quote: 'Quote' }[c.service];
const team = { repair: s.repair_team_email, installation: s.installation_team_email, quote: s.quote_team_email }[c.service];
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const record = {
  service: c.service, priority: b.priority, customer_name: c.name, customer_email: c.email, customer_phone: a.phone || '',
  topic: a.topic, description: a.description || '', urgency: a.urgency || '', preferred_date: a.preferred_date || '',
  units: a.units ?? null, property_type: a.property_type || '', budget: a.budget || '', decision_timeframe: a.decision_timeframe || '', company: a.company || '',
};
const rows = [['Service', label], ['Priority', record.priority], ['Name', record.customer_name], ['Email', record.customer_email], ['Phone', record.customer_phone],
  ['Topic', record.topic], ['Urgency', record.urgency], ['Units', record.units], ['Property', record.property_type], ['Budget', record.budget],
  ['Decision', record.decision_timeframe], ['Company', record.company], ['Preferred date', record.preferred_date], [c.service === 'installation' ? 'Access notes' : 'Details', record.description]]
  .filter(([, v]) => v !== '' && v !== null && v !== undefined);
const details_html = '<table cellpadding="4">' + rows.map(([k, v]) => '<tr><td><b>' + k + '</b></td><td>' + esc(v).replace(/\n/g, '<br>') + '</td></tr>').join('') + '</table>';
return [{ json: { ...record, service_label: label, team_email: String(team ?? '').trim(), details_html } }];

