// Completion text written for the answers given, and honest about what happened to the request.
const s = $('Service Request Settings').first().json;
const r = $('Build Request Record').first().json;
// Only a stored row has createdAt; a failed insert can leave on either output carrying its input item.
const saved = $('Save Request').all().find((i) => i.json.createdAt !== undefined);
const ref = saved ? '#' + saved.json.id : '';
// Flag Email Failed only runs when Email Team took its error output.
const emailed = !$('Flag Email Failed').isExecuted;
// The completion page renders HTML, so every value typed by the visitor is escaped.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const first = esc(r.customer_name.split(' ')[0]);
const fmt = (d) => d ? DateTime.fromISO(d, { zone: $now.zoneName }).toFormat('d LLLL yyyy') : '';
const reach = 'call ' + esc(s.contact_phone) + ' or email ' + esc(s.contact_email);
if (!ref && !emailed) return [{ json: { title: 'Request not received', message: 'Sorry, ' + first + ', something went wrong on our side and your request was not recorded. Please ' + reach + ' instead.' } }];
const refText = ref ? ' ' + ref : '';
const urgent = r.service === 'repair' && r.priority === 'urgent';
// The team email failed: promise nothing, tell the visitor how to reach the team directly.
if (!emailed) return [{ json: {
  title: urgent ? 'Emergency request saved, team not alerted' : r.service_label + ' request saved, team not alerted',
  message: 'Thanks, ' + first + '. Your ' + (urgent ? 'emergency ' : '') + r.service_label.toLowerCase() + ' request' + refText + ' is saved, but we could not alert our team, so nobody may have seen it yet. Please ' + reach + (urgent ? ' now so a technician can help you.' : ' so we can follow up.'),
} }];
let title, message;
if (urgent) {
  title = 'Emergency repair request received';
  message = 'Thanks, ' + first + '. Your emergency repair request' + refText + ' (' + esc(r.topic) + ') is with our repair team. A technician will call you on ' + esc(r.customer_phone) + ' ' + s.urgent_response + '.';
} else if (r.service === 'repair') {
  title = 'Repair request received';
  message = 'Thanks, ' + first + '. Your repair request' + refText + ' (' + esc(r.topic) + ') is in. Our repair team will email ' + esc(r.customer_email) + ' ' + s.standard_response + ' to book a visit on or near ' + fmt(r.preferred_date) + '.';
} else if (r.service === 'installation') {
  title = 'Installation request received';
  message = 'Thanks, ' + first + '. Your installation request' + refText + ' for ' + r.units + ' x ' + esc(r.topic) + ' (' + esc(r.property_type) + ') is in. Our installation team will contact you ' + s.standard_response + ' to confirm a date close to ' + fmt(r.preferred_date) + '.';
} else {
  title = 'Quote request received';
  message = 'Thanks, ' + first + '. Your quote request' + refText + ' is in. Our sales team will send your quote to ' + esc(r.customer_email) + ' ' + s.standard_response + (r.priority === 'hot lead' ? ', so you have it well before you decide' : '') + '.';
}
if (!ref) message += ' Please keep this page: our team has your details but there is no reference number this time.';
return [{ json: { title, message } }];
